package com.rikkeibank.account.domain;import jakarta.persistence.*;import java.math.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames="accountNumber"))public class Account{@Id private UUID id;@Column(nullable=false)private String accountNumber;@Column(nullable=false)private UUID customerId;@Column(nullable=false)private UUID accountTypeId;@Column(nullable=false,precision=19,scale=2)private BigDecimal balance;@Column(nullable=false)@Enumerated(EnumType.STRING)private Status status;@Version private long version;private Instant createdAt;protected Account(){}public Account(String n,UUID c,UUID t,BigDecimal b){id=UUID.randomUUID();accountNumber=n;customerId=c;accountTypeId=t;balance=b.setScale(2,RoundingMode.HALF_EVEN);status=Status.ACTIVE;createdAt=Instant.now();}public void debit(BigDecimal a){balance=balance.subtract(a);}public void credit(BigDecimal a){balance=balance.add(a);}public void update(UUID t,Status s){accountTypeId=t;status=s;}public UUID getId(){return id;}public String getAccountNumber(){return accountNumber;}public UUID getCustomerId(){return customerId;}public UUID getAccountTypeId(){return accountTypeId;}public BigDecimal getBalance(){return balance;}public Status getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public enum Status{ACTIVE,FROZEN,CLOSED}}

